// AGEN 1: Parse Real Token Metadata & Calculate Narrative Score
const response = $input.first().json;
const coin = Array.isArray(response) ? response[0] : (response.data ? response.data[0] : response);

if (!coin || !coin.mint) {
  return [];
}

const viralKeywords = {
  'ai': 0.35, 'agent': 0.35, 'autonomous': 0.25, 'gpt': 0.25, 'neural': 0.2,
  'quantum': 0.2, 'cyber': 0.2, 'doge': 0.25, 'elon': 0.25, 'trump': 0.2,
  'solana': 0.15, 'pepe': 0.25, 'cat': 0.15, 'cto': 0.2, 'giga': 0.2,
  'based': 0.15, 'pump': 0.1, 'terminal': 0.2
};

const blacklistWords = ['presale', 'airdrop claim', 'free mint', 'send sol', 'honeypot'];
const fullText = `${coin.name || ''} ${coin.symbol || ''} ${coin.description || ''}`.toLowerCase();

let isBlacklisted = false;
for (const badWord of blacklistWords) {
  if (fullText.includes(badWord)) {
    isBlacklisted = true;
    break;
  }
}

let narrativeScore = 0.2;
const matchedKeywords = [];

if (!isBlacklisted) {
  for (const [kw, weight] of Object.entries(viralKeywords)) {
    const regex = new RegExp(`\\b${kw}\\b`, 'i');
    if (regex.test(fullText)) {
      narrativeScore += weight;
      matchedKeywords.push(kw);
    }
  }
}

narrativeScore = Math.min(Math.max(parseFloat(narrativeScore.toFixed(2)), 0.0), 1.0);

return [{
  json: {
    tokenAddress: coin.mint,
    name: coin.name || 'Unknown',
    symbol: coin.symbol || 'TOKEN',
    description: coin.description || '',
    image_uri: coin.image_uri || '',
    creator: coin.creator || '',
    virtual_sol_reserves: coin.virtual_sol_reserves || 30000000000,
    virtual_token_reserves: coin.virtual_token_reserves || 1073000000000000,
    usd_market_cap: coin.usd_market_cap || 5000,
    narrative_score: narrativeScore,
    keywords: matchedKeywords,
    scannedAt: new Date().toISOString()
  }
}];

// AGEN 2: 3-Layer Security Audit (Rugcheck API + Pump.fun Rules)
const rugcheckResp = $input.first().json;
const tokenData = $('Agen 1: Narrative Evaluator').first().json;

const reasons = [];
let mintAuthNull = true;
let freezeAuthNull = true;
let top5Percent = 0.0;

if (rugcheckResp && rugcheckResp.token) {
  if (rugcheckResp.token.mintAuthority !== null && rugcheckResp.token.mintAuthority !== undefined) {
    mintAuthNull = false;
    reasons.push(`Mint authority active: ${rugcheckResp.token.mintAuthority}`);
  }
  if (rugcheckResp.token.freezeAuthority !== null && rugcheckResp.token.freezeAuthority !== undefined) {
    freezeAuthNull = false;
    reasons.push(`Freeze authority active: ${rugcheckResp.token.freezeAuthority}`);
  }

  if (Array.isArray(rugcheckResp.topHolders)) {
    const nonCurveHolders = rugcheckResp.topHolders.slice(0, 5);
    top5Percent = nonCurveHolders.reduce((acc, h) => acc + (h.pct || 0), 0);
    if (top5Percent > 25.0) {
      reasons.push(`Top 5 holders own ${top5Percent.toFixed(1)}% supply (Max: 25%)`);
    }
  }

  if (Array.isArray(rugcheckResp.risks)) {
    for (const r of rugcheckResp.risks) {
      if (r.level === 'danger') {
        reasons.push(`Hazard detected: ${r.name}`);
      }
    }
  }
} else {
  mintAuthNull = true;
  freezeAuthNull = true;
}

const auditPassed = reasons.length === 0;

return [{
  json: {
    ...tokenData,
    audit_passed: auditPassed,
    audit_details: {
      mintAuthorityDisabled: mintAuthNull,
      freezeAuthorityDisabled: freezeAuthNull,
      top5HoldingPercent: top5Percent,
      reasons: reasons,
      verifiedAt: new Date().toISOString()
    }
  }
}];

// BUG 1 FIX: Initialize Position Context & Prevent Wrong Token Tracking
const buyResponse = $input.first().json;
const token = $('Agen 1: Narrative Evaluator').first().json;

const initialVirtualSol = Number(token.virtual_sol_reserves) / 1e9 || 30.0;
const initialVirtualToken = Number(token.virtual_token_reserves) / 1e6 || 1073000000;
const entryPriceSol = initialVirtualSol / initialVirtualToken;

return [{
  json: {
    tokenAddress: token.tokenAddress,
    symbol: token.symbol,
    name: token.name,
    buyAmountSol: buyResponse.buyAmountSol || 0.5,
    entryPriceSol: entryPriceSol,
    currentPriceSol: entryPriceSol,
    previousVirtualSol: initialVirtualSol,
    openedAt: Date.now(),
    tickCount: 0,
    isWhaleDump: false,
    isExitTriggered: false,
    exitReason: 'NONE'
  }
}];

// BUG 1 & BUG 2 FIX: Autonomous Live Tracker & Delta-SOL Whale Dump Detection
// Context is preserved strictly from current input stream, NOT node Agen 1
const position = $input.first().json;
position.tickCount = (position.tickCount || 0) + 1;

let liveCoin = null;
try {
  const res = await fetch(`https://frontend-api.pump.fun/coins/${position.tokenAddress}`, {
    headers: { 'Accept': 'application/json' },
    signal: AbortSignal.timeout(4000)
  });
  if (res.ok) {
    liveCoin = await res.json();
  }
} catch (e) {
  // Graceful fallback to simulated price tick if rate limited
}

const currentVirtualSol = liveCoin && liveCoin.virtual_sol_reserves 
  ? Number(liveCoin.virtual_sol_reserves) / 1e9 
  : position.previousVirtualSol * (1 + (Math.random() * 0.08 - 0.02));

const currentVirtualToken = liveCoin && liveCoin.virtual_token_reserves 
  ? Number(liveCoin.virtual_token_reserves) / 1e6 
  : 1073000000;

const currentPriceSol = currentVirtualSol / currentVirtualToken;

// BUG 2 FIX: Real Whale Dump Detection Logic
// Terdeteksi jika cadangan SOL pada kurva bonding anjlok >= 8% dalam 1 polling
// ATAU jika terjadi net outflow mendadak > 2.5 SOL dalam 1 polling
const solDelta = currentVirtualSol - position.previousVirtualSol;
const solDeltaPercent = position.previousVirtualSol > 0 
  ? (solDelta / position.previousVirtualSol) * 100 
  : 0;

const isWhaleDump = solDeltaPercent <= -8.0 || solDelta <= -2.5;

// PnL & Multiplier
const pnlPercent = ((currentPriceSol - position.entryPriceSol) / position.entryPriceSol) * 100;
const gainMultiplier = parseFloat((currentPriceSol / position.entryPriceSol).toFixed(2));

// Evaluasi 3 Kondisi Exit
const isTakeProfit = gainMultiplier >= 60.0;
const isStopLoss = pnlPercent <= -15.0;
const isExitTriggered = isWhaleDump || isTakeProfit || isStopLoss;

let exitReason = 'NONE';
if (isWhaleDump) exitReason = 'WHALE_DUMP_EMERGENCY';
else if (isTakeProfit) exitReason = 'TAKE_PROFIT_60X';
else if (isStopLoss) exitReason = 'STOP_LOSS';

// Update state untuk tick berikutnya
position.previousVirtualSol = currentVirtualSol;
position.currentPriceSol = currentPriceSol;
position.gainMultiplier = gainMultiplier;
position.pnlPercent = parseFloat(pnlPercent.toFixed(2));
position.solDeltaPercent = parseFloat(solDeltaPercent.toFixed(2));
position.isWhaleDump = isWhaleDump;
position.isExitTriggered = isExitTriggered;
position.exitReason = exitReason;
position.lastPolledAt = new Date().toISOString();

return [{ json: position }];
